import React from "react";
import styled from "@emotion/styled";
import { css, Global } from "@emotion/react";

/* ================= DATA ================= */

const timelineData = [
  {
    date: "1914",
    datetime: "1914",
    title: "Archduke's Assassination & War Declaration",
    content: [
      "Assassination of Archduke Franz Ferdinand of Austria.",
      "Germany declares war on France."
    ]
  },
  {
    date: "1915",
    datetime: "1915",
    title: "New Fronts Open",
    content: [
      "First Zeppelin raid on Great Britain.",
      "Italy declares war on Austria-Hungary."
    ]
  },
  {
    date: "1916",
    datetime: "1916",
    title: "Major Battles",
    content: [
      "The Gallipoli Campaign ends.",
      "Battle of Dobrich."
    ]
  }
];

/* ================= GLOBAL STYLES ================= */

const GlobalStyles = () => (
  <Global
    styles={css`
      body {
        margin: 0;
        padding: 2rem;
        font-family: system-ui, sans-serif;
        background: #f3f4f6;
        color: #111827;
      }
    `}
  />
);

/* ================= STYLED COMPONENTS ================= */

const TimelineList = styled.ol`
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 2rem;
`;

const TimelineItemLi = styled.li`
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 3rem;
`;

const TimelineDate = styled.div`
  font-size: 2rem;
  font-weight: 200;
  color: #6b7280;
  text-align: right;
`;

const TimelineArticle = styled.article`
  position: relative;
  padding-left: 1rem;

  &::before {
    content: "";
    position: absolute;
    left: -1.6rem;
    top: 0.6rem;
    width: 1rem;
    height: 1rem;
    background: #3b82f6;
    border-radius: 50%;
  }
`;

const Title = styled.h3`
  margin: 0 0 0.5rem;
`;

const Content = styled.div`
  p {
    margin: 0 0 0.5rem;
  }
`;

/* ================= COMPONENTS ================= */

function TimelineItem({ date, title, content }) {
  return (
    <TimelineItemLi>
      <TimelineDate>{date}</TimelineDate>
      <TimelineArticle>
        <Title>{title}</Title>
        <Content>
          {content.map((text, i) => (
            <p key={i}>{text}</p>
          ))}
        </Content>
      </TimelineArticle>
    </TimelineItemLi>
  );
}

function App() {
  return (
    <>
      <GlobalStyles />
      <TimelineList>
        {timelineData.map((item, i) => (
          <TimelineItem key={i} {...item} />
        ))}
      </TimelineList>
    </>
  );
}

export default App;
